import type { GeneratedProject } from '@splendor/dapp-spec';
import { isSafeRelativePath, sdkSource } from './vendor';

function b64ToUint8(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** Zip the generated files under a `<name>/` folder and download it. */
export async function downloadZip(project: GeneratedProject): Promise<void> {
  const { default: JSZip } = await import('jszip');
  const zip = new JSZip();
  const root = zip.folder(project.name)!;
  for (const [path, contents] of Object.entries(project.files)) {
    if (!isSafeRelativePath(path)) throw new Error(`Refusing to export unsafe file path: ${path.slice(0, 80)}`);
    if (path.endsWith('.wasm.b64')) {
      const wasmPath = path.replace(/\.b64$/, '');
      root.file(wasmPath, b64ToUint8(contents));
      continue;
    }
    root.file(path, contents);
  }
  const blob = await zip.generateAsync({ type: 'blob', compression: 'DEFLATE' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${project.name}-${project.framework}.zip`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

/** Open the project in StackBlitz (WebContainers run `npm install && npm run dev` in the browser). */
export async function openInStackBlitz(project: GeneratedProject, title: string): Promise<void> {
  const unsafe = Object.keys(project.files).find((p) => !isSafeRelativePath(p));
  if (unsafe) throw new Error(`Refusing to export unsafe file path: ${unsafe.slice(0, 80)}`);
  const size = payloadBytes(project.files);
  if (size > STACKBLITZ_MAX_BYTES) {
    const mb = (n: number) => (n / 1024 / 1024).toFixed(1);
    throw new Error(`This project is ${mb(size)} MB, more than StackBlitz accepts (${mb(STACKBLITZ_MAX_BYTES)} MB). Download the .zip instead.`);
  }
  const { default: sdk } = await import('@stackblitz/sdk');
  sdk.openProject(
    {
      title,
      description: `Generated by the Splendor dApp Studio (SDK: ${sdkSource()})`,
      template: 'node',
      files: project.files,
    },
    {
      newWindow: true,
      openFile: project.framework === 'vite' ? 'src/App.tsx' : 'app/providers.tsx',
    },
  );
}

const SEGMENT = /^[\w.-]+$/;

/**
 * Repository root on a known host: `owner/repo` on GitHub and Bitbucket; on GitLab also
 * subgroups (`group/sub/repo`), but not a page inside a repo (`/-/tree/main`).
 */
export function isRepoUrl(repoUrl: string): boolean {
  const m = /^https:\/\/(github\.com|gitlab\.com|bitbucket\.org)\/([^?#]+?)\/?$/.exec(repoUrl.trim());
  if (!m) return false;
  const parts = m[2]!.split('/');
  if (!parts.every((p) => SEGMENT.test(p) && p !== '-' && p !== '.' && p !== '..')) return false;
  return m[1] === 'gitlab.com' ? parts.length >= 2 && parts.length <= 20 : parts.length === 2;
}

/** One-click deploy links for a repository the user has pushed the export to. */
export function deployLinks(repoUrl: string): { vercel: string; netlify: string } | null {
  const url = repoUrl.trim();
  if (!isRepoUrl(url)) return null;
  return {
    vercel: `https://vercel.com/new/clone?repository-url=${encodeURIComponent(url)}`,
    netlify: `https://app.netlify.com/start/deploy?repository=${encodeURIComponent(url)}`,
  };
}

/** Import links for a GitHub repository the studio just pushed (Vercel's importer, Netlify's deploy flow). */
export function importLinks(repoUrl: string): { vercel: string; netlify: string } | null {
  const url = repoUrl.trim();
  if (!isRepoUrl(url)) return null;
  return {
    vercel: `https://vercel.com/new/import?s=${encodeURIComponent(url)}`,
    netlify: `https://app.netlify.com/start/deploy?repository=${encodeURIComponent(url)}`,
  };
}

/**
 * Larger projects fail inside StackBlitz's form post (the browser or their API gives up) with no
 * useful message, so refuse them up front and point at the zip.
 */
export const STACKBLITZ_MAX_BYTES = 12 * 1024 * 1024;

export function payloadBytes(files: Record<string, string>): number {
  let n = 0;
  for (const [k, v] of Object.entries(files)) n += k.length + v.length;
  return n;
}
